'use strict';
// taskmote new-module: turn a skill folder (SKILL.md with frontmatter name +
// description, plus optional extra files) into a module folder that passes the
// module contract on its first run. See docs/MODULES.md, "From a skill".
// Writes only inside <modulesDir>/<name>/. The generated files carry no absolute
// path, user name or machine name. The module is never enabled: modules are off
// unless config "modules" says true (config/harness.config.json lists the defaults).
const fs = require('fs');
const path = require('path');

const NAME_RE = /^[a-z][a-z0-9-]{1,40}$/;
const MAX_FILES = 200, MAX_BYTES = 5 * 1024 * 1024;
const SKIP_DIRS = new Set(['.git', 'node_modules']);
const one = s => String(s).replace(/\s+/g, ' ').trim();

// SKILL.md text -> { meta: {key: string}, body }. Throws a clear Error without frontmatter.
function parseSkill(text) {
  const src = String(text).replace(/^﻿/, '').replace(/\r\n?/g, '\n');
  const m = /^---[ \t]*\n([\s\S]*?)\n---[ \t]*(?:\n|$)/.exec(src);
  if (!m) throw new Error('SKILL.md has no YAML frontmatter (expected a leading --- block with name and description)');
  const meta = {};
  const lines = m[1].split('\n');
  for (let i = 0; i < lines.length; i++) {
    const kv = /^([A-Za-z_][\w-]*):[ \t]*(.*)$/.exec(lines[i]);
    if (!kv) continue;
    let v = kv[2].trim();
    if (/^[>|][+-]?$/.test(v)) { // block scalar: the indented lines that follow
      const parts = [];
      while (i + 1 < lines.length && (/^\s+/.test(lines[i + 1]) || lines[i + 1] === '')) parts.push(lines[++i].trim());
      v = parts.join(' ');
    } else if (v === '') { // plain multi-line value: indented continuation lines
      const parts = [];
      while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1])) parts.push(lines[++i].trim());
      v = parts.join(' ');
    } else if (/^(["']).*\1$/.test(v)) {
      v = v.slice(1, -1);
    }
    meta[kv[1]] = one(v);
  }
  for (const k of ['name', 'description']) if (!meta[k]) throw new Error(`SKILL.md frontmatter has no "${k}"`);
  return { meta, body: src.slice(m[0].length).replace(/^\n+/, '') };
}

function listExtras(dir) { // regular files other than SKILL.md, relative, forward slashes
  const out = []; let bytes = 0;
  const walk = rel => {
    for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
      const r = rel ? rel + '/' + e.name : e.name;
      if (e.isDirectory()) { if (!SKIP_DIRS.has(e.name)) walk(r); } else if (e.isFile() && r !== 'SKILL.md') {
        bytes += fs.statSync(path.join(dir, r)).size;
        out.push(r);
        if (out.length > MAX_FILES || bytes > MAX_BYTES) throw new Error(`skill folder has too many extra files (limit ${MAX_FILES} files, ${MAX_BYTES >> 20} MB)`);
      }
    }
  };
  walk('');
  return out.sort();
}

function indexJs(name, description, fromSkill) {
  const head = `'use strict';
// ${name}: generated by \`taskmote new-module\`${fromSkill ? ' from a skill' : ''}. Off by default: add "${name}": true
// under "modules" in the config to turn it on (docs/MODULES.md).
`;
  if (!fromSkill) return head + `
module.exports = {
  contract: 2,
  name: ${JSON.stringify(name)},
  description: ${JSON.stringify(description)},
  runsOn: 'main',
  settings: {},
};
`;
  return head + `const fs = require('fs');
const path = require('path');

module.exports = {
  contract: 2,
  name: ${JSON.stringify(name)},
  description: ${JSON.stringify(description)},
  runsOn: 'main',

  // Before each engine turn: the skill text (skill.md, frontmatter removed) as context.
  // Set the include_skill setting to false to keep the module on but silent.
  prepareTurn(ctx) {
    const s = ctx && ctx.settings;
    if (s && s.include_skill === false) return null;
    return { context: [fs.readFileSync(path.join(__dirname, 'skill.md'), 'utf8')] };
  },

  // Settings: config section ${JSON.stringify(name.replace(/-/g, '_'))}.
  settings: {
    include_skill: { type: 'boolean', default: true, description: 'add the skill text to each turn' },
  },
};
`;
}

function testJs(name, fromSkill) {
  return `#!/usr/bin/env node
'use strict';
// ${name} suite (generated): the manifest validates, contract is 2${fromSkill ? ', prepareTurn returns the skill text' : ''}.
const fs = require('fs');
const path = require('path');
const MOD = path.resolve(__dirname, '..');
const ROOT = path.resolve(MOD, '..', '..');
const M = require(path.join(ROOT, 'lib', 'modules.js'));

let fails = 0;
const check = (label, ok, info) => { if (!ok) fails++; console.log(\`\${ok ? 'PASS' : 'FAIL'} \${label}\${!ok && info !== undefined ? ': ' + String(info).slice(0, 300) : ''}\`); };

(async () => {
  try {
    const m = require(path.join(MOD, 'index.js'));
    let err = null;
    try { M.validate(m, ${JSON.stringify(name)}, MOD); } catch (e) { err = e.message; }
    check('manifest validates with no errors', err === null, err);
    check('contract is 2', m.contract === 2, m.contract);
    check('name matches the folder', m.name === path.basename(MOD), m.name);
${fromSkill ? `    const skill = fs.readFileSync(path.join(MOD, 'skill.md'), 'utf8');
    check('skill.md is not empty', skill.trim().length > 0);
    const r = await m.prepareTurn({});
    check('prepareTurn returns the skill text', !!r && Array.isArray(r.context) && r.context.length === 1 && r.context[0] === skill, JSON.stringify(r));
    const off = await m.prepareTurn({ settings: { include_skill: false } });
    check('include_skill=false returns nothing', off === null, JSON.stringify(off));
` : ''}  } catch (e) { check('suite ran', false, e && e.stack || e); }
  console.log(\`result: \${fails ? fails + ' failing' : 'all passed'}\`);
  process.exit(fails ? 1 : 0);
})();
`;
}

// newModule(name, { fromSkill, force, modulesDir }) -> { dir, files: [relative paths] }. Throws Error with a clear message.
function newModule(name, opts = {}) {
  const modulesDir = path.resolve(opts.modulesDir || path.join(__dirname, '..', 'modules'));
  if (typeof name !== 'string' || !NAME_RE.test(name)) throw new Error(`bad module name ${JSON.stringify(name)}: use lowercase letters, digits and dashes, starting with a letter, 2 to 41 characters (${NAME_RE})`);
  let skill = null, extras = [], skillDir = null;
  if (opts.fromSkill) {
    skillDir = path.resolve(opts.fromSkill);
    const f = path.join(skillDir, 'SKILL.md');
    if (!fs.existsSync(f) || !fs.statSync(f).isFile()) throw new Error('--from-skill: no SKILL.md in that folder');
    skill = parseSkill(fs.readFileSync(f, 'utf8'));
    extras = listExtras(skillDir);
  }
  const dir = path.join(modulesDir, name);
  if (path.dirname(dir) !== modulesDir) throw new Error('refusing to write outside the modules folder');
  if (fs.existsSync(dir)) {
    if (!opts.force) throw new Error(`modules/${name} already exists; use --force to overwrite it`);
    fs.rmSync(dir, { recursive: true, force: true });
  }
  const files = {};
  const skillName = skill ? skill.meta.name : null;
  files['index.js'] = indexJs(name, skill ? skill.meta.description : `TODO: describe ${name}`, !!skill);
  files['tests.json'] = JSON.stringify({ suites: [{ label: name, file: 'test/run.js', needs: [] }] }, null, 2) + '\n';
  files['test/run.js'] = testJs(name, !!skill);
  files['DECISIONS.md'] = `# Decisions: ${name}\n\nModule-owned log. Append only, one line per decision with the reason.\n\n- ${skill ? `generated from skill ${skillName}` : 'generated by taskmote new-module (no skill)'}\n`;
  const lic = skill && skill.meta.license ? `license: ${skill.meta.license}` : 'license: unknown, check before publishing';
  files['PROVENANCE.md'] = `# Provenance: ${name}\n\n` + (skill
    ? `- source: skill folder "${path.basename(skillDir)}" (skill name: ${skillName})\n- ${lic}\n- skill.md is the SKILL.md body without its frontmatter${extras.length ? `; ${extras.length} extra file(s) copied to files/` : ''}\n`
    : `- written new by taskmote new-module; no outside source\n`);
  if (skill) files['skill.md'] = skill.body;
  fs.mkdirSync(dir, { recursive: true });
  const written = [];
  const put = (rel, data) => { const p = path.join(dir, rel); fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, data); written.push(rel); };
  for (const [rel, data] of Object.entries(files)) put(rel, data);
  for (const rel of extras) put('files/' + rel, fs.readFileSync(path.join(skillDir, rel)));
  return { dir, files: written.sort() };
}

// CLI: args after the verb.
function cli(args) {
  const usage = 'usage: taskmote new-module <name> [--from-skill <dir>] [--force]';
  const opts = {}; let name = null;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--force') opts.force = true;
    else if (args[i] === '--from-skill') { opts.fromSkill = args[++i]; if (!opts.fromSkill) throw new Error(usage); }
    else if (args[i].startsWith('--') || name !== null) throw new Error(usage);
    else name = args[i];
  }
  if (name === null) throw new Error(usage);
  const r = newModule(name, opts);
  console.log(`created modules/${name}/ (${r.files.length} files). It is off by default; to turn it on add "${name}": true under "modules" in your config. Test: node test/run-all.js module ${name}`);
  return 0;
}

module.exports = { newModule, parseSkill, cli, NAME_RE };
